(()=>{'use strict';let editing=false,editingProject='';const previousStage=stage;const names={reference_images:'参考图',first_frame:'仅首帧',first_last_frames:'首尾帧'};const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(typeof tabs!=='undefined')tabs[3]='分镜连接';
function locked(s){return videoBusy(s.videoJob)||(typeof videoBatchActive==='function'&&videoBatchActive()&&currentVideoBatch.entries?.some(e=>e.target_id===(s.shot_id||s.id)&&['pending','preparing_frames','submitting','running'].includes(e.status)));}
function firstChoice(s,i){return s.frameImages?.first?.sourceChoice||(s.frameImages?.first?.autoFromPrevious||i>0?'previous':'own');}
function summary(s){return s.connectionSummary||s.action||s.description||s.sub_shots?.map(x=>x.visual_action).join('；')||s.title||'';}
function status(s,i){if(data.shotScript?.endpoint_generation_policy?.strategy==='next_shot_first'){const own=ShotMethods.selected(s,'first'),next=data.shots[i+1],image=next&&ShotMethods.selected(next,'first');return (own?.image_url?'本镜首图已就绪':'本镜首图待生成')+(next?' · '+next.shot_id+' 首图'+(image?.image_url?'已就绪':'待生成'):' · 最后一镜仅首帧');}const method=ShotMethods.method(s),first=ShotMethods.selected(s,'first'),last=ShotMethods.selected(s,'last');if(method==='reference_images')return '使用人物、场景参考图';let text=first?.image_url?(first.source_target_id?'已接 '+first.source_target_id+' 尾帧':'已选本镜首帧'):i>0&&firstChoice(s,i)==='previous'?'等待上一镜尾帧':'缺少首帧';if(method==='first_last_frames')text+=last?.image_url?' · 尾帧已选':' · 缺少尾帧';return text;}
function updatePreview(row,s){const box=row.querySelector('[data-connection-preview]');if(!box)return;const video=selectedShotVideo(s),frame=ShotMethods.selected(s,'first'),url=video?.status==='completed'&&video.video_url?video.video_url:frame?.image_url||'',type=video?.status==='completed'&&video.video_url?'video':'image',key=type+'|'+url;if(box.dataset.previewKey===key)return;box.dataset.previewKey=key;box.replaceChildren();if(!url){box.textContent='未生成';return;}const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.title=type==='video'?'打开本镜视频':'查看首帧';link.setAttribute('aria-label',(s.shot_id||s.id)+(type==='video'?' 视频预览':' 首帧预览'));const label=document.createElement('small'),labelBase=type==='video'?'已生成视频':'已生成首帧';const setResolution=(w,h)=>{label.textContent=labelBase+(w>0&&h>0?' · '+w+' × '+h+' px':'');};const asset=type==='video'?video:frame;setResolution(asset?.width,asset?.height);if(type==='video'){const player=document.createElement('video');player.preload='metadata';player.muted=true;player.playsInline=true;player.style.pointerEvents='none';player.addEventListener('loadedmetadata',()=>{setResolution(player.videoWidth,player.videoHeight);if(player.duration>.15)player.currentTime=.1;},{once:true});player.src=url;link.append(player);}else{const image=document.createElement('img');image.loading='lazy';image.alt=(s.shot_id||s.id)+' 首帧缩略图';image.addEventListener('load',()=>setResolution(image.naturalWidth,image.naturalHeight),{once:true});image.src=url;link.append(image);}box.append(link,label);}
function refreshRow(row,s,i){updatePreview(row,s);const preview=row.querySelector('[data-connection-preview]'),completed=selectedShotVideo(s);let remove=preview.querySelector('[data-connection-delete]');if(completed?.status==='completed'&&completed.video_url){if(!remove){remove=document.createElement('button');remove.type='button';remove.dataset.connectionDelete='true';remove.textContent='删除视频';remove.style.cssText='margin-top:7px;padding:5px 10px;font-size:12px;color:#e8bcb9';remove.onclick=()=>deleteShotVideoRecords(s,remove);preview.append(remove);}remove.disabled=locked(s);}else remove?.remove();const firstImage=ShotMethods.selected(s,'first');let deleteFirst=preview.querySelector('[data-connection-delete-first]');if(completed?.status!=='completed'&&firstImage?.image_url){if(!deleteFirst){deleteFirst=document.createElement('button');deleteFirst.type='button';deleteFirst.dataset.connectionDeleteFirst='true';deleteFirst.textContent='删除首图';deleteFirst.style.cssText='margin-top:7px;padding:5px 10px;font-size:12px;color:#e8bcb9';deleteFirst.onclick=()=>deleteShotFirstImage(s,deleteFirst);preview.append(deleteFirst);}deleteFirst.disabled=locked(s);}else deleteFirst?.remove();const method=ShotMethods.method(s),busy=locked(s),choice=row.querySelector('[data-connection-source]');row.querySelector('[data-connection-status]').textContent=status(s,i);row.querySelector('[data-connection-method]').disabled=busy;choice.disabled=busy||method==='reference_images'||data.shotScript?.endpoint_generation_policy?.strategy==='next_shot_first';choice.value=firstChoice(s,i);row.querySelector('[data-connection-duration]').textContent=Number(s.duration_seconds??s.duration)+'秒';}
function refreshStatuses(){const table=document.querySelector('#shotConnections');if(tab!==3||!table||table.dataset.projectId!==data.project_id)return;for(const row of table.querySelectorAll('[data-connection-row]')){const i=data.shots.findIndex(s=>(s.shot_id||s.id)===row.dataset.connectionRow);if(i>=0)refreshRow(row,data.shots[i],i);}}
async function changeSource(s,i,value,select){if(locked(s))return;if(value==='previous'&&i===0){toast('第一镜没有上一镜');return;}s.frameImages??={};const state=s.frameImages.first??={versions:[]};if(value==='own'){state.sourceChoice='own';state.autoFromPrevious=false;const own=(state.versions||[]).filter(v=>!v.source_target_id&&v.status==='completed');state.activeId=own.at(-1)?.id||null;save();refreshStatuses();return;}select.disabled=true;const projectId=data.project_id,prev=data.shots[i-1],source=selectedShotVideo(prev);try{if(source?.status==='completed'&&source.video_url){if(typeof flushDisk==='function')await flushDisk();if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先读取最新项目后再修改');const selected=ShotMethods.selected(s,'first');let image=selected?.source_id===source.id?selected:await frontFetch('/api/shot-frame/adopt-previous',{project_id:projectId,target_id:s.shot_id||s.id,source_kind:'previous_video',source_id:source.id});if(data.project_id!==projectId)return;state.versions??=[];if(!state.versions.some(v=>v.id===image.id))state.versions.push(image);state.activeId=image.id;}else state.activeId=(state.versions||[]).filter(v=>v.source_target_id===prev.shot_id).at(-1)?.id||null;state.sourceChoice='previous';state.autoFromPrevious=true;state.needsReview=false;save();refreshStatuses();}catch(e){toast(e.message);refreshStatuses();}finally{select.disabled=locked(s)||ShotMethods.method(s)==='reference_images';}}
function draw(){const p=document.querySelector('#panel');p.innerHTML='<div class="section-head"><div><h3>分镜连接</h3><p>按顺序查看动作和生成方式，直接调整首尾衔接。修改用于后续生成。</p></div></div><div class="connection-table-wrap"><table id="shotConnections"><thead><tr><th>预览</th><th>分镜</th><th>简要动作</th><th>生成方式</th><th>首帧来源</th><th>衔接状态</th><th>操作</th></tr></thead><tbody>'+data.shots.map((s,i)=>{const id=s.shot_id||s.id,method=ShotMethods.method(s);return '<tr data-connection-row="'+safe(id)+'"><td><div class="connection-preview" data-connection-preview></div></td><td><b>'+safe(id)+'</b><div>'+safe(s.title||'')+'</div><small data-connection-duration></small></td><td><textarea rows="3" maxlength="500" aria-label="'+safe(id)+' 简要动作" data-connection-summary>'+safe(summary(s))+'</textarea></td><td><select aria-label="'+safe(id)+' 生成方式" data-connection-method>'+Object.entries(names).map(([k,n])=>'<option value="'+k+'" '+(method===k?'selected':'')+'>'+n+'</option>').join('')+'</select></td><td><select aria-label="'+safe(id)+' 首帧来源" data-connection-source><option value="own">本镜首帧</option><option value="previous" '+(i===0?'disabled':'')+'>上一镜尾帧'+(i>0?' · '+safe(data.shots[i-1].shot_id||data.shots[i-1].id):'')+'</option></select></td><td><span data-connection-status></span></td><td><button type="button" data-connection-frames>编辑首尾帧</button><button type="button" data-connection-video>生成设置</button></td></tr>';}).join('')+'</tbody></table></div>';const table=p.querySelector('#shotConnections');table.dataset.projectId=data.project_id;
for(const row of table.querySelectorAll('[data-connection-row]')){const i=data.shots.findIndex(s=>(s.shot_id||s.id)===row.dataset.connectionRow),s=data.shots[i];row.querySelector('[data-connection-summary]').onchange=e=>{s.connectionSummary=e.target.value.trim();save();};row.querySelector('[data-connection-method]').onchange=e=>{if(locked(s)){e.target.value=ShotMethods.method(s);return;}s.videoMethodOverride=e.target.value;if(typeof batchVideoMethod!=='undefined'){batchVideoMethod='per_shot';localStorage.setItem('frame-batch-video-method','per_shot');}if(typeof videoBatchPreview!=='undefined')videoBatchPreview=null;save();refreshRow(row,s,i);};row.querySelector('[data-connection-source]').onchange=e=>changeSource(s,i,e.target.value,e.target);row.querySelector('[data-connection-frames]').onclick=()=>{si=i;editing=true;editingProject=data.project_id;render();};row.querySelector('[data-connection-video]').onclick=()=>{si=i;shotMode='shots';tab=2;render();};refreshRow(row,s,i);}}
stage=function(){if(tab!==3){previousStage();return;}if(editing&&editingProject===data.project_id){previousStage();const back=document.createElement('button');back.type='button';back.textContent='← 返回分镜连接';back.style.marginBottom='16px';back.onclick=()=>{editing=false;render();};document.querySelector('#panel').prepend(back);return;}editing=false;draw();};
const css=document.createElement('style');css.textContent='.connection-table-wrap{overflow-x:auto;border:1px solid #354556;border-radius:12px}#shotConnections{width:100%;border-collapse:collapse;min-width:980px}#shotConnections th,#shotConnections td{text-align:left;padding:14px;vertical-align:top;border-bottom:1px solid #354556}#shotConnections th{background:#17232f;white-space:nowrap}#shotConnections td:nth-child(2){min-width:150px;max-width:200px}#shotConnections td:nth-child(2) div{margin:6px 0;color:#b5c5d6}#shotConnections td:nth-child(3){width:35%;min-width:280px}#shotConnections textarea{width:100%;min-height:88px;resize:vertical;margin:0}#shotConnections select{min-width:120px;margin:0}#shotConnections td:nth-child(6){min-width:150px;color:#b6daca}#shotConnections td:last-child button{display:block;margin:0 0 8px;white-space:nowrap}';document.head.append(css);const previewStyle=document.createElement('style');previewStyle.textContent='.connection-preview{width:136px;min-height:94px;color:#a7bbcb;font-size:12px}.connection-preview a{display:block;width:136px;height:77px;border-radius:7px;overflow:hidden;background:#0b1119}.connection-preview video,.connection-preview img{display:block;width:100%;height:100%;object-fit:contain}.connection-preview small{display:block;margin-top:5px}#shotConnections .connection-preview .image-resolution-label,#shotConnections .connection-preview .role-image-tools{display:none!important}';document.head.append(previewStyle);setInterval(refreshStatuses,5000);render();})();